{
  "findings": [
    {
      "ref": "[R439]",
      "area": "money",
      "claim": "A parent reports that a $6 purchase did not give them the promised minecoins.",
      "stance": "risk",
      "quote": "Purchase didnt go through but paid Minecraft is a fun game but my $6 purchase didnt give me my minecoins after the purchase. I want my minecoins!!!"
    },
    {
      "ref": "[R466]",
      "area": "data",
      "claim": "A parent reports that worlds and data may be lost due to repeated crashes after updates.",
      "stance": "risk",
      "quote": "This is a big bug issue I’ve had for a long time. After each update, (especially smaller ones) my game glitches where I can’t SEE the world saves, but they’re still there(if I try hard with muscle memory, I can still play- but it’s extremely difficult) . No buttons, nothing but that rotating world screen. Each time if I want to play the game again, I have to uninstall it and loose all my worlds then reinstall to play again. I’ve lost around 80+ worlds just from wanting to play the game."
    },
    {
      "ref": "[R473]",
      "area": "contact",
      "claim": "A child reports that they cannot play at all because the app crashes immediately on launch.",
      "stance": "risk",
      "quote": "I’ve been playing Minecraft religiously for YEARS, but recently I haven’t been able to open the app whatsoever. I’ll click into it, wait, and then it immediately crashes—just POOF! I miss being able to play this game and I really want to explore new worlds and continue building in my current ones. Please fix this."
    },
    {
      "ref": "[R477]",
      "area": "money",
      "claim": "A parent reports that adding mods before an update caused the app to become unusable, potentially leading to loss of progress.",
      "stance": "risk",
      "quote": "Minecraft is absolutely amazing, highly recommend it, but never install Minecraft Addons Maker mods right before an update, because now I’m locked out of Minecraft entirely because it’s glitched. It keeps booting me while it’s loading. PLEASE HELP ME. IVE TRIED EVERYTHING, I REALLY DONT WANT TO NEVER PLAY AGAIN. PLEASE. SOMEBODY. MOJANG. Update: I'm a literal pro at this game and pretty close to legendary level. I've tried every advanced troubleshooting step, cleared the caches, and checked the directories, but nothing works. PLEASE HELP, THIS IS REALLY STRESSING ME OUT. I WORKED SO HARD ON ALL MY WORLDS, USED COMPLICATED COMMANDS AND NPCS, AND I REALLY CANT LOSE THIS."
    },
    {
      "ref": "[R486]",
      "area": "money",
      "claim": "A parent reports that the Bedrock edition forces microtransactions like minecoins, which they view as a monetization trap.",
      "stance": "risk",
      "quote": "So my glitches I found were stripelands and opaque water in dappled forest but the most thing I HATE is the minecoin gimmick like it’s only in bedrock why don’t you add it to Java or remove minecoins from bedrock also Minecraft does not work now because it’s 26.51 and I’m on the iPad Air 2"
    },
    {
      "ref": "[R489]",
      "area": "data",
      "claim": "A parent reports that the app crashes before any data can be accessed, indicating potential data loss or corruption.",
      "stance": "risk",
      "quote": "Ok this is gonna be short, but recently there’s been a bug happening that crashes the minecraft app before you can actually play. Once opening the app, the texts Mojang appear, and then the screen flashes white as it suddenly crashes."
    },
    {
      "ref": "[R491]",
      "area": "content",
      "claim": "A parent reports that a white screen bug kicks the user out after 2 seconds, preventing gameplay.",
      "stance": "risk",
      "quote": "I have played this for a while and I’m starting a creative world with my brother and some of his friends, we are having fun but today I was gonna play by myself but there is a white screen iOS only bug that kicks you out after 2 seconds of the white screen, IVE heard it’s fixed, but I have to wait on my client for it to update."
    },
    {
      "ref": "[R492]",
      "area": "content",
      "claim": "A parent reports that the game crashes with a white screen and rotating world screen, making it unplayable.",
      "stance": "risk",
      "quote": "This is a great game all the way up to the newer updates. There is a weird bug where when I launch the game, the screen is white. It rotates twice, then crashes the application."
    },
    {
      "ref": "[R499]",
      "area": "contact",
      "claim": "A child reports that the app kicks them off immediately when trying to play.",
      "stance": "risk",
      "quote": "It kicks me off when I try to play"
    },
    {
      "ref": "[R500]",
      "area": "money",
      "claim": "A parent reports that the app is unusable due to a persistent glitch, potentially wasting money on the purchase.",
      "stance": "risk",
      "quote": "Mojang I hope you check the app store reviews every once in a while because everyone playing minecraft mobile can’t play minecraft anymore 😭😭😭 please helppp"
    }
  ]
}
